-- Kiem tra so dong moi bang sau khi chay:
SELECT 'nguoidung' AS bang, COUNT(*) AS so_dong FROM nguoidung;
SELECT 'nhacungcap' AS bang, COUNT(*) AS so_dong FROM nhacungcap;
SELECT 'vuonuom' AS bang, COUNT(*) AS so_dong FROM vuonuom;
SELECT 'danhmuc' AS bang, COUNT(*) AS so_dong FROM danhmuc;
SELECT 'caycanh' AS bang, COUNT(*) AS so_dong FROM caycanh;
SELECT 'yeucausinhtruong' AS bang, COUNT(*) AS so_dong FROM yeucausinhtruong;
SELECT 'tonkho' AS bang, COUNT(*) AS so_dong FROM tonkho;
SELECT 'taptintruyenthong' AS bang, COUNT(*) AS so_dong FROM taptintruyenthong;
SELECT 'diachigiaohang' AS bang, COUNT(*) AS so_dong FROM diachigiaohang;
SELECT 'donhang' AS bang, COUNT(*) AS so_dong FROM donhang;
SELECT 'chitietdonhang' AS bang, COUNT(*) AS so_dong FROM chitietdonhang;
SELECT 'danhgia' AS bang, COUNT(*) AS so_dong FROM danhgia;
-- Kiem tra tong tien don hang (0 = khong sai lech):
SELECT COUNT(*) AS so_don_sai FROM (
 SELECT d.madonhang FROM donhang d JOIN chitietdonhang ct ON ct.madonhang=d.madonhang
 GROUP BY d.madonhang,d.tongtien,d.phivanchuyen
 HAVING d.tongtien <> SUM(ct.thanhtien)+d.phivanchuyen
) x;
